import { useEffect, useRef, useState } from 'react';
import { Menu as MenuIcon, X } from 'lucide-react';
import Hero from './components/Hero';
import Work from './components/Work';
import About from './components/About';

// Domain design tokens (resolved server-side by the design system).
const tw = {"page_bg": "bg-white", "surface": "bg-stone-50", "surface_2": "bg-stone-100", "heading_text": "text-stone-900", "body_text": "text-stone-600", "muted_text": "text-stone-500", "primary": "bg-stone-900", "primary_hover": "hover:bg-stone-700", "on_primary": "text-white", "border": "border-stone-200", "accent_text": "text-orange-600", "accent_bg": "bg-orange-50", "gradient": "from-stone-900 to-stone-600"};
const RADIUS = "rounded-xl";
const GRAD = "bg-gradient-to-br from-stone-900 to-stone-600";
const FONT_CSS = ".font-display{font-family: 'Space Grotesk', system-ui, sans-serif;} .font-body{font-family: 'Inter', system-ui, sans-serif;} body{font-family: 'Inter', system-ui, sans-serif;}";
const LOGO_URL = "";

// Scroll-reveal wrapper: sections animate in as they enter the viewport
// (IntersectionObserver; no-ops during server render).
function Reveal({ children }) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return undefined;
    const io = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting) { setVisible(true); io.disconnect(); }
    }, { threshold: 0.12 });
    io.observe(el);
    // Fallback: embedded/short viewports may never fire the observer
    // (live: preview iframes without scroll) -- never leave content invisible.
    const t = setTimeout(() => { setVisible(true); io.disconnect(); }, 1200);
    return () => { clearTimeout(t); io.disconnect(); };
  }, []);
  return (
    <div ref={ref} className={`reveal ${visible ? 'reveal-visible' : ''}`}>{children}</div>
  );
}

export default function App() {
  const [menuOpen, setMenuOpen] = useState(false);
  const links = [
    { label: "Work", href: "#work" },
    { label: "About", href: "#about" },
  ];
  return (
    <div className={`min-h-screen ${tw.page_bg} ${tw.heading_text} font-body`}>
      <style>{FONT_CSS}</style>
      <header className={`sticky top-0 z-50 backdrop-blur-xl border-b ${tw.page_bg} ${tw.border}`}>
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <a href="#top" className="flex items-center gap-2">
            {LOGO_URL ? (
              <img src={LOGO_URL} alt="Mara Lindqvist" className="h-9 w-auto" />
            ) : (
              <span className={`w-9 h-9 ${GRAD} flex items-center justify-center ${tw.on_primary} font-black text-sm tracking-tight ${RADIUS}`}>ML</span>
            )}
            <span className="font-display font-extrabold text-lg tracking-tight">Mara Lindqvist</span>
          </a>
          <nav className={`hidden md:flex items-center gap-8 text-sm font-medium ${tw.body_text}`}>
            {links.map(l => <a key={l.href} href={l.href} className="hover:opacity-70 transition-opacity">{l.label}</a>)}
          </nav>
          <div className="hidden md:flex items-center gap-3">
            <a href="#top" className={`px-4 py-2 ${tw.primary} ${tw.primary_hover} ${tw.on_primary} text-sm font-semibold ${RADIUS} transition-colors`}>Get started</a>
          </div>
          <button className="md:hidden p-2" onClick={() => setMenuOpen(!menuOpen)} aria-label="Menu">
            {menuOpen ? <X className="w-5 h-5" /> : <MenuIcon className="w-5 h-5" />}
          </button>
        </div>
        {menuOpen && (
          <div className={`md:hidden border-t px-6 py-4 space-y-3 ${tw.surface} ${tw.border}`}>
            {links.map(l => <a key={l.href} href={l.href} onClick={() => setMenuOpen(false)} className={`block font-medium ${tw.body_text}`}>{l.label}</a>)}
            <a href="#top" className={`block text-center px-4 py-2.5 ${tw.primary} ${tw.on_primary} font-semibold ${RADIUS}`}>Get started</a>
          </div>
        )}
      </header>
      <main id="top">
      <Reveal><Hero /></Reveal>
      <Reveal><Work /></Reveal>
      <Reveal><About /></Reveal>
      </main>
      <footer className={`border-t py-10 text-center text-sm ${tw.border} ${tw.muted_text}`}>
        <div className="flex items-center justify-center gap-2 mb-2">
          {LOGO_URL ? (
            <img src={LOGO_URL} alt="Mara Lindqvist" className="h-7 w-auto" />
          ) : (
            <span className={`w-7 h-7 ${GRAD} flex items-center justify-center ${tw.on_primary} font-black text-[11px] ${RADIUS}`}>ML</span>
          )}
          <span className="font-display font-bold">Mara Lindqvist</span>
        </div>
        &copy; 2026 Mara Lindqvist. All rights reserved.
      </footer>
    </div>    );
}

import React, { useState } from 'react';
import { Mail, Sparkles, CheckCircle2, Briefcase, Camera, ArrowUpRight, Filter, Search, X, Plus } from 'lucide-react';

const projects = [
