    overlayGradient: 'from-stone-500/20 via-stone-500/10 to-transparent',
    date: 'Apr 2022 - Jul 2023'
  }
];

export default function Work() {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('All');
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [selectedProject, setSelectedProject] = useState(null);

  const filteredProjects = projects.filter(item => {
    const titleMatch = item.title.toLowerCase().includes(searchTerm.toLowerCase());
    const categoryMatch = filterCategory === 'All' || item.category.toLowerCase() === filterCategory.toLowerCase();
    return titleMatch && categoryMatch;
  });

  const handleSelect = (project) => {
    setSelectedProject(project);
    setIsAddOpen(true);
  };

  const handleClose = () => {
    setSelectedProject(null);
    setIsAddOpen(false);
  };

  return (
    <div className="min-h-screen bg-stone-900 text-stone-600 font-sans antialiased">
      {/* Decorative Gradient Header Bar */}
      <div className="h-48 bg-gradient-to-br from-stone-700 to-stone-800 bg-blend-multiply p-4 shadow-2xl">
        <div className="container mx-auto flex items-center justify-between px-6">
          <div>
            <h1 className="text-4xl font-black text-transparent bg-clip-text bg-gradient-to-r from-white via-stone-300 to-transparent">
              Work
            </h1>
            <p className="text-stone-600 text-sm mt-1">Selected projects from the past year</p>
          </div>
          <button
            onClick={() => setIsAddOpen(true)}
            className="p-2 bg-stone-100 text-stone-600 border border-stone-200 rounded-lg hover:bg-stone-100 transition-all duration-300 shadow-lg shadow-stone-500/10"
          >
            <Plus className="w-5 h-5 text-stone-600" />
          </button>
        </div>
      </div>

      {/* Main Work Section */}
      <div className="container mx-auto px-6 pb-24">
        <div className="mb-16 flex flex-col items-center justify-center text-center">
          <div className="w-full max-w-sm text-center rounded-3xl bg-stone-100 p-4 backdrop-blur-xl border border-stone-200 shadow-2xl shadow-stone-500/10">
            <div className="mb-6 flex items-center justify-center">
              <Filter className="w-6 h-6 text-orange-400" />
              <span className="ml-3 text-sm tracking-wide text-stone-600">Filter & Search</span>
            </div>
            <div className="relative mb-8">
              <Search className="absolute left-3 top-1.5 w-4 h-4 text-stone-600" />
              <input
                type="text"
                placeholder="Search projects..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-stone-100 border border-stone-200 rounded-lg py-2 pl-10 pr-4 text-stone-600 placeholder:text-stone-600 focus:ring-2 focus:ring-stone-500/30 outline-none transition-all duration-200"
              />
            </div>
            <div className="mb-10 flex flex-wrap gap-4">
              {['All', 'E-commerce', 'Identity', 'Subscription'].map((cat) => (
                <button
                  key={cat}
                  onClick={() => setFilterCategory(cat)}
                  className={`py-2 px-3 rounded-xl border transition-colors duration-200 ${
                    cat === filterCategory ? 'border-stone-500 bg-stone-500/10 text-orange-400' : 'border-stone-200 text-stone-600 hover:text-stone-600 hover:border-stone-200'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </div>
            <div className="space-y-4">
              {filteredProjects.map((p) => (
                <div
                  key={p.id}
                  className="relative group rounded-2xl border border-stone-200 bg-stone-100 backdrop-blur-xl p-6 transition-all duration-300 hover:border-stone-200 hover:shadow-lg hover:scale-[1.01] hover:shadow-stone-500/10"
                >
                  <div className="absolute -inset-0.5 bg-stone-100 backdrop-blur-md rounded-2xl" />
                  <div className="relative flex flex-col overflow-hidden rounded-2xl bg-stone-100 p-6 backdrop-blur-xl border border-stone-200 hover:border-stone-200 transition-all duration-300 hover:shadow-lg hover:shadow-stone-500/10">
                    <div className="relative mb-6 flex flex-col items-start gap-2">
                      <h2 className="text-lg font-semibold tracking-wide text-stone-600">{p.title}</h2>
                      <p className="text-xs text-stone-600">{p.date}</p>
                    </div>
                    <div className="mb-6 flex items-start justify-between gap-3">
                      <div className="flex flex-col gap-1">
                        <span className="text-xs text-stone-600">{p.category}</span>
                        <span className="text-xs font-semibold text-stone-600">{p.role}</span>
                      </div>
                      <div className="flex items-center gap-1">
                        <span className="text-xs text-stone-600">{p.stackBadge}</span>
                        <Sparkles className="w-3.5 h-3.5 text-orange-400" />
                      </div>
                    </div>
                    <div className="relative">
                      <div className="absolute -inset-0.5 bg-stone-100 backdrop-blur-md rounded-xl" />
                      <p className="text-sm text-stone-600">{p.summary}</p>
                    </div>
                    <div className="mt-6 flex flex-col gap-3">
                      <button
                        onClick={() => handleSelect(p)}
                        className="inline-flex justify-center gap-2 rounded-xl bg-stone-100 px-4 py-2 text-sm font-medium text-stone-600 hover:bg-stone-100 border border-stone-200 hover:border-stone-200 transition-all duration-200 active:scale-95 hover:shadow-lg hover:shadow-stone-500/10"
                      >
                        <ArrowUpRight className="w-4 h-4 text-stone-600" /> Explore
                      </button>
                      {selectedProject && (
                        <button
                          onClick={handleClose}
                          className="inline-flex justify-center gap-2 rounded-xl bg-stone-100 px-4 py-2 text-sm font-medium text-stone-600 hover:bg-stone-100 border border-stone-200 hover:border-stone-200 transition-all duration-200 active:scale-95 hover:shadow-lg hover:shadow-stone-500/10"
                        >
                          <X className="w-4 h-4 text-stone-600" /> Close
                        </button>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

.font-display { font-family: 'Space Grotesk', system-ui, sans-serif; }
.font-body { font-family: 'Inter', system-ui, sans-serif; }
body { font-family: 'Inter', system-ui, sans-serif; }

@keyframes reveal-up { from { opacity: 0; transform: translateY(28px); } to { opacity: 1; transform: translateY(0); } }
.reveal { opacity: 0; }
.reveal-visible { animation: reveal-up 0.8s cubic-bezier(0.22, 1, 0.36, 1) both; }
@media (prefers-reduced-motion: reduce) {
  .reveal { opacity: 1; }
  .reveal-visible { animation: none; }
}
@keyframes fade-up { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: translateY(0); } }
.animate-fade-up { animation: fade-up 0.7s ease-out both; }
@keyframes float-slow { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-10px); } }
.animate-float-slow { animation: float-slow 5s ease-in-out infinite; }
@keyframes marquee { from { transform: translateX(0); } to { transform: translateX(-50%); } }
.animate-marquee { animation: marquee 30s linear infinite; }

